WITH filtered_transactions AS (SELECT * FROM transactions WHERE txn_type IN ('DEBIT', 'FEE')), agg AS (SELECT CASE WHEN amount >= 3100 THEN 'high' WHEN amount >= 1800 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(amount) AS total_amount FROM filtered_transactions GROUP BY CASE WHEN amount >= 3100 THEN 'high' WHEN amount >= 1800 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, total_amount FROM agg WHERE total_amount > 14000 ORDER BY total_amount DESC
